reference_solution:
def closest_fair_integer(n):
    def fair(value):
        digits=str(value)
        return len(digits)%2==0 and sum(int(digit)%2 for digit in digits)*2==len(digits)
    length=len(str(n))
    if length%2:
        zeros=(length+1)//2
        return int('1'+'0'*zeros+'1'*(zeros-1))
    while not fair(n):n+=1
    return n

